"""Install shrink_gui into the tree: python/shrink_gui/ (the GUI that submits
and follows the runs on inti), with its tests.

Writes these files, and nothing else:
    python/shrink_gui/__init__.py
    python/shrink_gui/__main__.py
    python/shrink_gui/app.py
    python/shrink_gui/config.py
    python/shrink_gui/i18n.py
    python/shrink_gui/remote.py
    python/shrink_gui/remote_helper.py
    python/shrink_gui/runscripts.py
    python/shrink_gui/tests/conftest.py
    python/shrink_gui/tests/data/fake_stress.py
    python/shrink_gui/tests/fakes/ccc_mdel
    python/shrink_gui/tests/fakes/ccc_mprun
    python/shrink_gui/tests/fakes/ccc_msub
    python/shrink_gui/tests/fakes/squeue
    python/shrink_gui/tests/fakes/ssh
    python/shrink_gui/tests/test_gui.py
    python/shrink_gui/tests/test_i18n_and_events.py
    python/shrink_gui/tests/test_remote_helper.py
    python/shrink_gui/widgets.py

A file already there and identical is left alone; one that differs stops the
script before anything is written (pass --force to overwrite). Nothing is
removed: delete the old single-file shrink_gui.py yourself if you kept one.

Run from the repository root:  python3 install_shrink_gui.py [--force]
Then, on the laptop:           cd python && python3 -m shrink_gui
Tests:                         cd python && python3 -m pytest shrink_gui/tests -q
"""
import base64
import pathlib
import sys
import zlib

FILES = {
    'python/shrink_gui/__init__.py': (False, ''),
    'python/shrink_gui/__main__.py': (False, 'eNp1jzsSwjAMRHudYsc0zgwEBqjS03IFjwCHeII/2E6R2+NA+DSosbySVk9CiDDmzrsdVhapi8b16joYyDZ6i1dtXS3hI96Ns/htroUQZGzwMcOnd5bGRGRaKBX43PNVKwXjII/e6SWEqBp8YoE4OHAC42KiPmcfxwaWe43cacwGeDnz6aZpmiob6sC5q41LOma5KZizUlwcWy3//fmUplcq1ZpbIatKED1v/rmLQ5h3FpbCXjidv3ODw36zJZo0WdEDlyNrMw=='),
    'python/shrink_gui/app.py': (False, ''),
    'python/shrink_gui/config.py': (False, ''),
    'python/shrink_gui/i18n.py': (False, ''),
    'python/shrink_gui/remote.py': (False, ''),
    'python/shrink_gui/remote_helper.py': (False, ''),
    'python/shrink_gui/runscripts.py': (False, ''),
    'python/shrink_gui/tests/conftest.py': (False, ''),
    'python/shrink_gui/tests/data/fake_stress.py': (False, ''),
    'python/shrink_gui/tests/fakes/ccc_mdel': (True, 'eNody7EOgjAQBuC9T/FbCE6VsBrjpsTBRd1Ne73YysERiu+vcf++atOGPLXBl2QqnP3AIKLnGFlwyPG4x/3SP063K1bFmhhvDduCeVHiUvBa9DPvzJBF4P7MOThbdxZNA6aksL+BugP5iViEozVfPo4i9g=='),
    'python/shrink_gui/tests/fakes/ccc_mprun': (True, 'eNpVjT1vwjAYhHf/iotjgoRowtdECmKhWxfULYqQsU1t4dhRYgpS1f9OaGBgu/e95+7iKDsYlx14q0mMD35SEELsq7o5OxS+Dsa7tsS78FXFnUzTdL2EbHzdImiFBzBGh/efJ0iU0B60OL5Uls/EEux3NBjgPozRHyUXbaxCARbj7TtgghJJ0t2UTSmiVQ+WOaRHq80x3JVTJDS8xvBkrAUTXYXEbJ1J9ZO5s7U51NUETBfzIb62u09C2YYiwT+4YlGOC+/8PkhuNp5S9A=='),
    'python/shrink_gui/tests/fakes/ccc_msub': (True, ''),
    'python/shrink_gui/tests/fakes/squeue': (True, 'eNo1jk0LgkAYhO/+immzqGDb6JgUdKiIQOjDU0Ss+Ypv2S6pGx368WnRcWYeZqbdUjEbFesy89pY6huhfDhyBJlBOkT7xQ7SQnQYnYOYoMoIaYNdbVyirDjPoXN+EnRB2EVhuA5XQy+1BVKwgfCX883ivBVqECCxOEJSbaYCJ7zfuFhTsXEUgJOp36t/kNH3H9EPcGvq5aiWnAiMZyqhpzKuNrtd0CWz3+Q/K5oFQx69uMLI+wDkuz/x'),
    'python/shrink_gui/tests/fakes/ssh': (True, ''),
    'python/shrink_gui/tests/test_gui.py': (False, ''),
    'python/shrink_gui/tests/test_i18n_and_events.py': (False, ''),
    'python/shrink_gui/tests/test_remote_helper.py': (False, ''),
    'python/shrink_gui/widgets.py': (False, ''),
}


def main():
    force = "--force" in sys.argv[1:]
    if not pathlib.Path("python").is_dir():
        sys.exit("run from the repository root (python/ not found)")
    plan, differs = [], []
    for rel, (exe, blob) in FILES.items():
        data = zlib.decompress(base64.b64decode(blob))
        p = pathlib.Path(rel)
        if p.exists():
            if p.read_bytes() == data:
                continue
            differs.append(rel)
        plan.append((p, data, exe))
    if differs and not force:
        sys.exit("these files exist and differ (nothing written; --force to overwrite):\n  "
                 + "\n  ".join(differs))
    for p, data, exe in plan:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        if exe:
            p.chmod(p.stat().st_mode | 0o111)
    print(f"{len(plan)} file(s) written, {len(FILES) - len(plan)} already up to date")
    if pathlib.Path("python/shrink_gui.py").exists():
        print("note: python/shrink_gui.py (the old single file) is still there: python3 -m shrink_gui "
              "now runs the package; delete the old file when you no longer need it")


if __name__ == "__main__":
    main()
